"""One-page auto-generated scene summary (PDF) used by the app's export button."""
from __future__ import annotations

import io
import textwrap

import numpy as np
import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
from matplotlib.backends.backend_pdf import PdfPages  # noqa: E402


def summary_pdf(scene_name: str, image: np.ndarray, class_names: list[str], counts: np.ndarray,
                gsd_m: float | None, mean_conf: float | None, conf_label: str, metrics_rows: list[dict],
                limitations: list[str], method: str) -> bytes:
    """A4 portrait: map + class-area table + metrics + limitations."""
    buf = io.BytesIO()
    with PdfPages(buf) as pdf:
        fig = plt.figure(figsize=(8.27, 11.69))
        fig.text(0.05, 0.965, f"Spectral Earth Mini - scene summary: {scene_name}", fontsize=14, weight="bold")
        fig.text(0.05, 0.945, f"Method: {method}", fontsize=8)
        ax = fig.add_axes([0.05, 0.60, 0.42, 0.33])
        ax.imshow(image, interpolation="nearest")
        ax.set_xticks([]), ax.set_yticks([])
        # class areas
        tot = max(int(counts.sum()), 1)
        px_ha = (gsd_m ** 2) / 1e4 if gsd_m else None
        lines = ["Class areas (predicted, whole scene)", ""]
        for n, c in sorted(zip(class_names, counts), key=lambda t: -t[1]):
            if c == 0:
                continue
            area = f"{c * px_ha:8.1f} ha" if px_ha else ""
            lines.append(f"{n[:28]:28s} {int(c):7d} px {100 * c / tot:5.1f}% {area}")
        fig.text(0.50, 0.93, "\n".join(lines[:30]), fontsize=6.5, family="monospace", va="top")
        y = 0.56
        fig.text(0.05, y, f"Mean {conf_label}: {mean_conf:.3f}" if mean_conf is not None else "", fontsize=9)
        y -= 0.03
        fig.text(0.05, y, "Evaluation metrics (test set, mean ± sd over 3 seeds)" if metrics_rows else
                 "No labelled test data for this scene (see validation notes)", fontsize=9, weight="bold")
        y -= 0.02
        for r in metrics_rows:
            fig.text(0.05, y, r, fontsize=7.5, family="monospace")
            y -= 0.017
        y -= 0.02
        fig.text(0.05, y, "Limitations", fontsize=9, weight="bold")
        y -= 0.02
        for lim in limitations:
            for i, ln in enumerate(textwrap.wrap(lim, 120)):
                fig.text(0.05, y, ("- " if i == 0 else "  ") + ln, fontsize=7)
                y -= 0.015
        fig.text(0.05, 0.02, "Auto-generated by app.py. Pixel areas use the nominal ground sampling distance; "
                 "maps are not georeferenced.", fontsize=6, color="0.4")
        pdf.savefig(fig)
        plt.close(fig)
    return buf.getvalue()
